    public void Initialize(GameEngine gameEngine)
    {    
        var lines = new List<string>();
        using (var reader = new StreamReader("g_spriteNames.csv", Encoding.UTF8, detectEncodingFromByteOrderMarks: true))
        {
            string? line;
            while ((line = reader.ReadLine()) != null)
            {
                lines.Add(line.Split(";")[1]); //0:jp, 1:fr, 2:en
            }
        }

        g_spriteNames = lines.Skip(1).ToArray();

        //TODO : already loaded? where?
        g_imageBuffer = new byte[50000];
        g_imageBufferCompressed = new byte[50000];

        for (var i = 0; i < g_entitySlots.Length; i++)
        {
            var entity = new Entity { EntityRefId = -1 };
            g_entitySlots[i] = entity;
        }

        g_isGameEnding = 1; //force initialization
        g_gameRandomSeed = 0xB017C93D;
        g_tileToWorldXTable = new short[1248];
        g_playerStats = new PlayerStats();
        g_emptyEntityForClearing = new Entity();

        for (int i = 0; i < g_mapEvents.Length; i++)
        {
            g_mapEvents[i] = new MapEvent { Id = i };
        }

        var index2 = 0;
        var layoutIndex = 0;
        do
        {
            var tileOffset = 0;
            var innerTileIndex = layoutIndex;

            do
            {
                g_tileToWorldXTable[innerTileIndex] = (short)index2;
                tileOffset++;
                innerTileIndex = layoutIndex + tileOffset;
            } while (tileOffset < 0x18);

            index2++;
            layoutIndex += 0x18;
        } while (index2 < 0x34);

        for (int i = 0; i < g_effectSlots.Length; i++)
        {
            g_effectSlots[i] = new SpriteEffect { Status = 0 };
        }

